// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"tokenomics":{"slug":"tokenomics","cat":"basics","en":"Tokenomics","contentLocale":"zh-Hans","term":"代币经济学（Tokenomics）","aka":["Tokenomics","代币经济模型","经济模型"],"short":"代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。","body":[["看代币经济学主要看几件事：最大供应量和是否增发；初始分配给团队、投资人、社区、生态基金各多少；锁仓和解锁时间表；代币有什么用途（付手续费、治理、",["质押","staking"],"）；是否有回购或销毁机制。"],"分配结构影响抛压。如果团队和早期投资人合计持有 40% 以上，且解锁集中在上线后一两年内，市场就要持续消化这些供应。反之，用途清晰、需求能随使用量增长的代币，更有机会抵消新增供应。",["白皮书里的代币经济学不一定会严格执行，项目方可能修改参数。比较不同项目时，最好结合",["链上数据","on-chain-analysis"],"核对实际流通和大户持仓，而不只看宣传图。"]],"example":["假设某代币总量 10 亿枚：团队 20%、投资人 18%、社区激励 32%、生态基金 20%、初始流通 10%。上线时流通 1 亿枚。团队和投资人共 3.8 亿枚，锁仓一年后在 24 个月内线性解锁，每月约 1,583 万枚。也就是说，第二年起每个月",["流通量","circulating-supply"],"增加约 16%（相对于初始的 1 亿枚）。"],"mistakes":["只看项目故事，不看团队和投资人占比及解锁计划。","以为有“销毁机制”就一定通缩，没算清销毁量和增发量谁更大。","把白皮书的设定当成不可更改的事实。"],"faq":[{"q":"代币经济学好坏怎么判断？","a":"可以看分配是否过度集中、解锁是否平缓、代币有无真实用途和需求来源，以及增发与销毁是否平衡。没有统一标准，需要放在项目具体情况里看。"},{"q":"代币经济学去哪里查？","a":"通常在项目白皮书或官方文档中，第三方数据平台也会整理分配和解锁时间表，最好对照链上数据核实。"}],"title":"什么是代币经济学（Tokenomics）？怎么看","description":"代币经济学（Tokenomics）是什么？讲清供应量、分配比例、解锁时间表、代币用途和销毁机制，以及如何判断潜在抛压。","related":[["circulating-supply","流通量（Circulating Supply）","流通量是指当前已在市场上自由流通、可以被交易的代币数量，不包括仍处于锁仓或尚未发行的部分。"],["token-unlock","代币解锁（Token Unlock）","代币解锁是指原本锁仓、不能交易的代币按预定时间表释放进入流通，常见于团队、投资人和生态基金的份额。"],["fully-diluted-valuation","完全稀释估值（FDV）","完全稀释估值（FDV）是用当前价格乘以代币最大供应量（或总供应量）算出的估值，表示所有代币都流通后的理论市值。"],["token-burn","代币销毁（Token Burn）","代币销毁是把代币发送到无人掌握私钥的地址或由合约直接注销，使其永久退出流通，从而减少总供应量。"],["governance-token","治理代币（Governance Token）","治理代币是赋予持有人对协议或 DAO 提案投票权的代币，例如 UNI、AAVE，持有越多投票权越大，但不一定代表能分享协议收入。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"order-book":{"slug":"order-book","cat":"trading","en":"Order book","contentLocale":"zh-Hans","term":"订单簿（Order Book）","aka":["Order book","盘口","挂单簿","深度"],"short":"订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。","body":[["订单簿分为两边：买单（Bid）列出愿意买入的价格和数量，从高到低排列；卖单（Ask）列出愿意卖出的价格和数量，从低到高排列。最高买价和最低卖价之间的差就是",["买卖价差","bid-ask-spread"],"。中文圈常把它叫“盘口”。"],["订单簿的“深度”反映",["流动性","liquidity"],"：每个价位挂的数量越多，大额",["市价单","market-order"],"成交时价格移动越小。深度很浅的币，一笔不大的市价单就可能吃掉好几档价格，产生明显",["滑点","slippage"],"。"],["限价挂单会出现在订单簿上，成为挂单方（Maker）；市价单或立即成交的",["限价单","limit-order"],"会吃掉订单簿上的挂单，成为吃单方（Taker），两者手续费通常不同。注意订单簿上的大单可能随时撤销，不一定是真实意图。"]],"example":["假设 ",["ETH","ethereum"],"/USDT 订单簿卖方前三档是：3,000 USDT 挂 2 ETH，3,001 USDT 挂 3 ETH，3,003 USDT 挂 5 ETH。你用市价买入 6 ETH：先以 3,000 吃掉 2 个，再以 3,001 吃掉 3 个，最后以 3,003 买 1 个。总成本 6,000 + 9,003 + 3,003 = 18,006 USDT，均价 3,001 USDT，比显示的最优卖价高约 0.03%。"],"mistakes":["只看最新成交价，不看订单簿深度就下大额市价单。","把订单簿上的大额挂单当成可靠的支撑或阻力，没意识到它可能被撤掉。","分不清买方和卖方两侧，看错了价差。"],"faq":[{"q":"订单簿的深度是什么意思？","a":"深度指各价位挂单数量的总和，深度越大，市场越能承接大额交易而不让价格大幅移动。"},{"q":"DEX 也有订单簿吗？","a":"有些 DEX 和链上永续合约平台采用订单簿模式，比如 Hyperliquid；很多 DEX 则使用自动做市商（AMM）流动性池，没有传统订单簿。"}],"title":"什么是订单簿（Order Book）？怎么看盘口","description":"订单簿（盘口）是什么？讲清买单卖单如何排列、深度和价差怎么看、市价单如何吃掉多档挂单，以及挂单与吃单的区别。","related":[["bid-ask-spread","买卖价差（Bid-Ask Spread）","买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"屏幕上的价格，为什么不是我的成交价？"},"coin":null,"tool":null,"cta":true},"liquidity":{"slug":"liquidity","cat":"trading","en":"Liquidity","contentLocale":"zh-Hans","term":"流动性（Liquidity）","aka":["市场流动性","深度","liquidity"],"short":"流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。","body":[["在",["交易所","centralized-exchange"],"里，流动性主要体现在",["订单簿","order-book"],"上：",["买卖价差","bid-ask-spread"],"（买一和卖一之间的距离）有多窄，以及每个价位挂了多少数量，也就是常说的“深度”。",["BTC","bitcoin"],"、",["ETH","ethereum"]," 等主流币在大型交易所的深度很厚，几十万 ",["USDT","usdt"]," 的单子也很难把价格推动太多；小市值币可能挂单稀少，几万 USDT 就能吃穿好几档价格。"],"流动性差会带来三个实际问题：市价单滑点大，止损单在急跌时可能远低于触发价成交，想卖的时候找不到足够的买家。在去中心化交易所，流动性来自流动性池里锁定的资金，池子越大，同等金额交易造成的价格冲击越小。","同一个币在不同交易所、不同交易对上的流动性可能差很多，大额交易前先看订单簿深度，比只看价格更重要。"],"example":"假设你想市价买入 50,000 USDT 的某个小币。订单簿卖方：1.000 USDT 挂了价值 10,000 USDT，1.010 挂了 15,000 USDT，1.030 挂了 25,000 USDT。你的单会依次吃掉这三档，大约买到 49,123 个币，平均成交价约 1.018 USDT，比看到的 1.000 高出约 1.8%。同样 50,000 USDT 买 BTC，在深度好的交易所几乎感觉不到价格变化。","mistakes":["只看 K 线上的价格，不看订单簿深度，就对小币下大额市价单。","把交易所展示的高成交量当作流动性好，忽略刷量可能让成交量虚高。","在深度很薄的币上设置止损，以为一定会按止损价成交。"],"faq":[{"q":"流动性好意味着什么？","a":"意味着买卖价差窄、每个价位挂单多，你能以接近当前价格的价格快速买卖较大数量，滑点小。"},{"q":"怎么判断一个币的流动性？","a":"看订单簿的买卖价差和上下各档的挂单量，也可以看在多个主流交易所是否都有活跃交易对。只看 24 小时成交量容易被刷量误导。"}],"title":"流动性是什么意思？加密货币市场深度详解","description":"解释加密货币中的流动性和市场深度，为什么流动性差会导致滑点和止损失效，以及大额下单前该如何检查订单簿。","related":[["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"],["bid-ask-spread","买卖价差（Bid-Ask Spread）","买卖价差是订单簿上最高买价与最低卖价之间的差额，代表立即买入再立即卖出所要承担的隐性成本。"],["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"],["market-maker","做市商（Market Maker）","做市商是在订单簿上持续同时挂出买单和卖单、为市场提供流动性的交易者或机构，主要通过买卖价差和交易所的挂单返佣获利。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"屏幕上的价格，为什么不是我的成交价？"},"coin":null,"tool":null,"cta":false},"isolated-margin":{"slug":"isolated-margin","cat":"derivatives","en":"Isolated margin","contentLocale":"zh-Hans","term":"逐仓保证金（Isolated Margin）","aka":["逐仓","逐仓模式","isolated margin"],"short":"逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。","body":[["在逐仓模式下，你开仓时为这个仓位分配一笔固定的保证金。仓位亏损只从这笔保证金里扣，亏到",["维持保证金","maintenance-margin"],"水平就被",["强平","liquidation"],"，账户其他余额和别的仓位不受影响。你也可以手动给某个逐仓仓位",["追加保证金","margin-call"],"，把",["强平价","liquidation-price"],"推远。"],["逐仓的好处是风险边界清楚，适合高",["杠杆","leverage"],"的短线交易，或者同时做多个互不相关的仓位。缺点是每个仓位的缓冲有限，即使账户里还有大量闲置余额，也不会自动帮你扛住波动，所以强平价通常比全仓更近。"],["大多数",["交易所","centralized-exchange"],"允许在开仓前切换逐仓或全仓，但有持仓或挂单时可能无法切换。同一个交易对的多空双向持仓模式、统一账户等设置也会影响保证金计算方式，以交易所说明为准。"]],"example":"假设账户里有 10,000 USDT。你用逐仓开一笔 BTC 多单，分配 1,000 USDT 保证金，10 倍杠杆，仓位价值 10,000 USDT。若维持保证金率 0.5%，BTC 下跌约 9.5% 时这笔仓位就会被强平，你最多亏掉这 1,000 USDT，剩下的 9,000 USDT 不受影响。如果想扛更大波动，可以手动再加 500 USDT 保证金。","mistakes":["以为逐仓就安全，于是开很高杠杆，结果正常波动就被强平。","忘记自己用的是逐仓，以为账户余额会自动帮仓位扛亏损。","频繁给亏损的逐仓仓位追加保证金，等于把逐仓变成了没有上限的全仓。"],"faq":[{"q":"逐仓和全仓哪个好？","a":"逐仓把亏损限制在单个仓位的保证金内，风险边界清楚；全仓用全部余额作缓冲，不容易被强平，但一旦爆仓可能亏掉整个账户。按策略选择即可。"},{"q":"逐仓模式可以追加保证金吗？","a":"可以。手动增加保证金会让强平价远离当前价格，但同时增加了这笔仓位可能亏损的上限。"}],"title":"逐仓是什么意思？逐仓保证金模式详解","description":"解释合约交易中逐仓保证金模式的工作方式、它如何把亏损限制在单个仓位内，以及与全仓模式相比的优缺点和使用建议。","related":[["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。"],["portfolio-margin","组合保证金（Portfolio Margin）","组合保证金是一种按整个投资组合的净风险计算保证金的模式，现货、合约、期权的仓位可以互相抵消风险，对冲良好的组合所需保证金更低。"],["liquidation-price","强平价（Liquidation Price）","强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"]],"lesson":{"id":"E21","slug":"isolated-margin","ep":21,"title":"逐仓：把这笔交易装进独立小盒子"},"coin":null,"tool":null,"cta":false},"index-price":{"slug":"index-price","cat":"derivatives","en":"Index price","contentLocale":"zh-Hans","term":"指数价格（Index Price）","aka":["指数价","现货指数","index price"],"short":"指数价格是交易所根据多家主流现货交易所的价格，按一定权重加权计算出的综合现货价格，用作标记价格和资金费率的基准。","body":[["单一",["交易所","centralized-exchange"],"的现货价格可能出现异常，比如短暂断线或被大单砸穿。指数价格把多家交易所的现货报价合在一起，通常会剔除偏离太大的报价，并在某个数据源失联时自动调整权重，从而得到更稳定、更有代表性的价格。"],["指数价格是",["永续合约","perpetual-futures"],"体系的锚：",["资金费率","funding-rate"],"衡量合约价格相对指数价格的溢价或折价，",["标记价格","mark-price"],"以指数价格为基础计算，",["交割合约","delivery-futures"],"到期时也常用指数价格的平均值作为交割价格。"],"不同交易所选取的成分交易所和权重不同，所以同一个币在各家的指数价格会有小差异。交易所一般会在合约详情页公布指数成分。小币的成分交易所少，指数价格更容易受单一市场影响。"],"example":["假设某交易所的 ",["BTC","bitcoin"]," 指数由三家现货交易所等权重组成，报价分别是 60,010、59,990 和 60,030 USDT，指数价格 = (60,010 + 59,990 + 60,030) ÷ 3 = 60,010 USDT。如果第四家交易所突然报出 57,000 这种明显异常的价格，并被纳入计算，规则通常会把它剔除或降权，而不会让指数被拉低几百 USDT。"],"mistakes":["以为指数价格就是某一家交易所的现货价格。","不知道资金费率是根据合约价格相对指数价格的偏离计算的。","交易小币合约时没看指数成分，忽略单一现货市场异动对指数的影响。"],"faq":[{"q":"指数价格和标记价格有什么区别？","a":"指数价格是多家现货交易所的加权平均价；标记价格在指数价格的基础上加入合约的平滑基差，用于盈亏和强平计算。"},{"q":"指数价格从哪里来？","a":"由交易所选定的一组主流现货交易所报价加权计算而来，成分和权重一般在合约详情或指数说明页面公布。"}],"title":"指数价格是什么？合约指数价与标记价区别","description":"解释合约交易中指数价格的计算方法、为什么要用多家现货交易所加权，以及它与标记价格、资金费率和交割价格的关系。","related":[["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"],["last-price","最新价（Last Traded Price）","最新价是某个交易对在订单簿上最后一笔实际成交的价格，也是交易软件和K线图上默认显示的实时价格。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["oracle","预言机（Oracle）","预言机是把链下数据（如币价、汇率、体育比分）传送到区块链上供智能合约使用的服务，DeFi 借贷、衍生品和稳定币都依赖它获取价格。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"爆仓：谁按下了强制平仓按钮？"},"coin":null,"tool":"/funding-rates","cta":false},"yield-farming":{"slug":"yield-farming","cat":"defi","en":"Yield farming","contentLocale":"zh-Hans","term":"流动性挖矿（Yield Farming）","aka":["流动性挖矿","收益耕作","挖矿","Yield farming"],"short":"流动性挖矿是指把加密资产存入 DeFi 协议提供流动性或借贷，以赚取手续费、利息以及协议额外发放的代币奖励的做法。","body":[["协议为了吸引资金，会在正常的手续费或利息之外，额外向",["流动性","liquidity"],"提供者发放自家代币，这就是“",["挖矿","mining"],"”奖励。用户常把 LP 凭证再拿去",["质押","staking"],"，甚至把奖励代币卖出复投，以追求更高收益。"],["页面上的高 ",["APR","apr-vs-apy"]," 往往主要来自奖励代币。代币价格下跌、参与者增多稀释收益，都会让实际收益远低于显示的数字。很多高收益池子在上线初期收益很高，随后迅速下降。"],["风险是叠加的：",["无常损失","impermanent-loss"],"、合约漏洞、奖励代币暴跌、",["跨链桥","cross-chain-bridge"],"风险，以及项目方跑路。越是层层嵌套的策略，任何一环出问题都会影响整体。"]],"example":"假设你向一个池子投入价值 10,000 USDT 的资产，页面显示年化 60%，其中 10% 来自手续费，50% 来自奖励代币。一个月后你按比例得到约 83 USDT 手续费和价值约 417 USDT 的奖励代币。但如果奖励代币在这期间下跌 70%，这部分只剩约 125 USDT，若再计入无常损失和 Gas 费，月收益可能所剩无几。","mistakes":["把页面显示的超高年化当作稳定收益。","收到奖励代币后一直持有，忽略它可能持续被抛售。","为了追求高收益把资产放进陌生协议的多层嵌套策略中。"],"faq":[{"q":"流动性挖矿和质押有什么区别？","a":"质押通常是锁定代币参与网络验证获得奖励；流动性挖矿是向 DeFi 协议提供资金换取手续费和代币奖励，涉及无常损失等更多风险。"},{"q":"流动性挖矿的收益为什么越来越低？","a":"资金涌入会稀释每份收益，奖励代币的发放量通常递减，代币价格也可能下跌，所以高年化往往难以持续。"}],"title":"什么是流动性挖矿？收益来源与风险","description":"流动性挖矿是什么意思？了解 Yield Farming 的收益由哪些部分组成、为什么页面年化往往难以兑现，以及新手常见的几种风险。","related":[["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"],["apr-vs-apy","APR 和 APY 的区别","APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。"],["impermanent-loss","无常损失（Impermanent Loss）","无常损失是指你在 AMM 流动性池中提供流动性时，因两种代币价格比例变化，导致取回资产的价值低于单纯持有这些代币所造成的差额。"],["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"mev":{"slug":"mev","cat":"defi","en":"MEV (maximal extractable value)","contentLocale":"zh-Hans","term":"MEV（最大可提取价值）","aka":["MEV","最大可提取价值","夹子","三明治攻击"],"short":"MEV（最大可提取价值）是指区块生产者或搜索者通过调整、插入或排除区块中交易的顺序所能额外获得的利润，三明治攻击（夹子）是最常见的例子。","body":[["你在 ",["DEX","dex"]," 上提交的交易在被打包前会先进入公开的",["内存池","mempool"],"（mempool），所有人都能看到。专门的机器人（搜索者）会寻找有利可图的机会，并付更高的费用让自己的交易排在你前面或后面。"],["三明治攻击的流程是：机器人发现你要用较高的",["滑点","slippage"],"容忍度买入某代币，就先买入推高价格，让你以更差的价格成交，随后立刻卖出获利。",["套利","arbitrage"],"和清算也属于 MEV，它们对市场有一定作用，但三明治攻击直接损害了普通用户。"],"降低被夹的方法：把滑点容忍度设得合理；大额交易拆单；使用支持防 MEV 的私有交易通道或 RPC；选择带有 MEV 保护的 DEX 聚合器。"],"example":["假设你想在 DEX 上用 5,000 ",["USDC","usdc"]," 买一个小",["市值","market-capitalization"],"代币，滑点容忍度设为 3%。机器人看到你的交易后先买入，把价格推高约 2%，你的交易随后以更差的价格成交，少拿到约 2%，相当于损失约 100 USDC；机器人接着卖出，把这部分差价收入囊中。如果你把滑点设为 0.5%，这笔夹子交易就会让你的交易失败，机器人难以获利。"],"mistakes":["为了确保成交把滑点设到 5% 甚至更高。","在流动性很浅的池子里通过公开内存池提交大额交易。","以为交易失败就是 DEX 出了问题，其实可能是滑点保护在起作用。"],"faq":[{"q":"怎么判断自己被夹了？","a":"在区块浏览器查看你的交易所在区块，如果紧挨着你前后有同一地址对同一代币的买入和卖出，基本可以判断遭遇了三明治攻击。"},{"q":"中心化交易所有 MEV 吗？","a":"链上 MEV 主要发生在公链交易中。中心化交易所的订单在内部撮合，不经过公开内存池，不存在同样形式的 MEV。"}],"title":"什么是 MEV？夹子机器人和三明治攻击","description":"MEV 最大可提取价值是什么？了解夹子机器人如何利用内存池对你的 DEX 交易进行三明治攻击，以及设置滑点和防 MEV 通道的方法。","related":[["mempool","内存池（Mempool）","内存池是区块链节点用来暂存已广播但尚未被打包进区块的交易的等待区，交易在这里排队，矿工或验证者通常优先打包手续费更高的交易。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"],["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"nft":{"slug":"nft","cat":"defi","en":"NFT (non-fungible token)","contentLocale":"zh-Hans","term":"NFT（非同质化代币）","aka":["NFT","非同质化代币","数字藏品","Non-fungible token"],"short":"NFT（非同质化代币）是区块链上每一枚都独一无二、不可互换的代币，常用来代表数字艺术、游戏道具、会员资格或域名等资产的所有权记录。","body":[["普通代币是同质化的：你的 1 ",["USDT","usdt"]," 和我的 1 USDT 完全一样。NFT 则每枚都有独立编号，在",["以太坊","ethereum"],"上常用 ERC-721 或 ERC-1155 标准。链上记录的是谁持有哪个编号，图片等内容通常存放在链下服务器或 IPFS 上，由元数据链接过去。"],["买入 NFT 一般不等于获得作品的版权，具体权利取决于项目条款。NFT 的价格由市场成交决定，许多系列的",["成交量","trading-volume"],"低，挂单价和实际能卖出的价格可能差很多。"],["NFT 领域是钓鱼重灾区：假铸造网站、免费",["空投","airdrop"]," NFT 引导你去“领取”、以及要求你对整个系列签署“全部授权”（setApprovalForAll）的恶意签名，都可能让你的 NFT 被一次性转走。"]],"example":"假设某系列 NFT 的地板价显示为 2 ETH，你持有其中一枚。但过去 7 天该系列只有 3 笔成交，买方最高出价只有 1.4 ETH。如果你急需卖出，实际能拿到的可能是 1.4 ETH，再扣除市场手续费和版税，比账面价值少 30% 以上。","mistakes":["把地板价当成自己 NFT 的可变现价值。","以为买了 NFT 就拥有了图片的版权。","点开钱包里莫名出现的空投 NFT 链接，并签署了全部授权。"],"faq":[{"q":"NFT 的图片存在链上吗？","a":"多数 NFT 只在链上记录编号和元数据链接，图片存在 IPFS 或普通服务器上；少数项目把内容完全存储在链上。"},{"q":"数字藏品和 NFT 一样吗？","a":"技术思路相近，但国内的数字藏品通常运行在联盟链上，一般不支持自由转售和二级交易，规则和 NFT 市场不同。"}],"title":"什么是 NFT？非同质化代币的含义与风险","description":"NFT 是什么意思？了解非同质化代币的技术原理、NFT 所有权与版权的区别、地板价与流动性问题，以及常见的 NFT 钓鱼手法。","related":[["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["token-approval","代币授权（Token Approval）","代币授权是你在链上允许某个智能合约动用你钱包里指定代币的操作，授权额度决定合约最多能转走多少，常用于 DEX 交易和 DeFi 存款。"],["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["coin-vs-token","币和代币的区别（Coin vs Token）","币（Coin）通常指一条区块链自己的原生资产，如 BTC、ETH；代币（Token）则是基于已有区块链的智能合约发行的资产，如以太坊上的 USDT。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"vasp":{"slug":"vasp","cat":"regulation","en":"VASP (virtual asset service provider)","contentLocale":"zh-Hans","term":"虚拟资产服务提供商（VASP）","aka":["VASP","虚拟资产服务商","CASP"],"short":"VASP是“虚拟资产服务提供商”的缩写，指为他人提供加密资产兑换、转账、托管或发行相关服务的企业，例如中心化交易所和托管钱包服务商。","body":[["VASP这个概念来自FATF的国际",["反洗钱","aml"],"标准。只要以商业方式代客户买卖、兑换、转移或保管虚拟资产，通常就属于VASP，需要履行KYC、反洗钱和",["旅行规则","travel-rule"],"等义务。欧盟的",["MiCA法规","mica"],"使用的类似概念叫CASP（加密资产服务提供商）。"],"在许多国家和地区，VASP必须向当地监管机构注册或取得牌照才能合法服务当地用户。注册和牌照的含金量差别很大：有的只是反洗钱登记，有的则包含资本金、客户资产隔离和定期审计等要求。",["对用户来说，查看一家",["交易所","centralized-exchange"],"是否在你所在地区注册或持牌，是判断平台合规性的基础一步。可以到当地监管机构的官方公示名单中核对公司名称和注册号，而不是只看平台自己的宣传。"]],"example":["假设你计划在一家交易所存入20,000 ",["USDT","usdt"],"。平台官网写着“全球持牌”，你去所在地监管机构的公示名单里查询，发现它的关联公司只在另一个国家完成了反洗钱登记，而不是你所在地区。另一家平台在你所在地区持有包含客户资产隔离要求的牌照。两相比较，即使后者手续费略高，你也能更清楚地知道出问题时适用哪里的规则。"],"mistakes":["看到“持牌”二字就放心，不核实牌照所在地区和牌照类型。","只看平台宣传页面，不去监管机构官方名单里核对公司名称。","以为在某一个国家注册就等于在全球所有地区都受保护。"],"faq":[{"q":"VASP和CASP有什么区别？","a":"VASP是FATF标准中的通用说法，CASP是欧盟MiCA法规中的用语，两者都指提供加密资产服务的企业，但适用的法律框架不同。"},{"q":"怎么查一家交易所是不是注册的VASP？","a":"到你所在地区金融监管机构的官网查询公开名单，核对公司全称和注册编号是否与交易所用户协议里的运营主体一致。"}],"title":"什么是VASP？虚拟资产服务提供商与牌照","description":"VASP是什么意思？了解虚拟资产服务提供商的定义、与欧盟CASP的区别，以及如何在监管机构名单中核实交易所是否注册。","related":[["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["mica","MiCA（欧盟加密资产市场法规）","MiCA是欧盟的《加密资产市场法规》，为加密资产发行方、稳定币和加密资产服务提供商（CASP）建立统一的许可和监管规则，适用于全部成员国。"],["travel-rule","旅行规则（Travel Rule）","旅行规则是FATF第16条建议对虚拟资产服务商的要求：在转账时收集并传递汇款方和收款方的身份信息，让资金和信息一起“旅行”。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"先认门，再注册：别把账户开在假平台"},"coin":null,"tool":"/topics/compliant-exchanges","cta":false},"mica":{"slug":"mica","cat":"regulation","en":"MiCA (EU Markets in Crypto-Assets)","contentLocale":"zh-Hans","term":"MiCA（欧盟加密资产市场法规）","aka":["MiCA","MiCA法规","欧盟加密资产市场法规"],"short":"MiCA是欧盟的《加密资产市场法规》，为加密资产发行方、稳定币和加密资产服务提供商（CASP）建立统一的许可和监管规则，适用于全部成员国。","body":[["MiCA分两步生效：",["稳定币","stablecoin"],"相关规则从2024年6月30日开始适用，加密资产服务提供商的规则从2024年12月30日开始适用。各成员国可以给已在运营的平台设置过渡期，最晚到2026年7月1日。"],["在稳定币方面，MiCA把稳定币分为电子货币代币（锚定单一法币，如欧元或美元）和资产参考代币，发行方需要取得授权并满足储备和赎回要求。因此，部分",["交易所","centralized-exchange"],"对欧洲经济区用户调整了不合规稳定币的",["交易对","trading-pair"],"，而Circle发行的USDC等已获授权的稳定币可以继续使用。"],"在服务商方面，取得CASP授权的平台可以凭“护照”机制在整个欧盟提供服务，同时要遵守客户资产隔离、信息披露、利益冲突管理等要求。MiCA只适用于欧盟，其他国家和地区有各自的规则。"],"example":["假设你住在欧盟，在交易所持有3,000 ",["USDT","usdt"],"。平台公告称，为符合MiCA，将限制欧洲经济区用户买入未获授权的稳定币，你可以继续持有或卖出，但无法再新买入。你把3,000 USDT按1:0.999换成USDC，得到2,997 ",["USDC","usdc"],"，之后用USDC交易对继续交易。这样做的成本约3美元，换来的是使用符合MiCA的稳定币。"],"mistakes":["以为MiCA在全球适用，非欧盟用户也必须遵守同样的限制。","看到平台调整稳定币交易对就恐慌性低价抛售。","不确认平台是否已取得CASP授权，或是否仍处于当地过渡期。"],"faq":[{"q":"MiCA什么时候开始实施？","a":"稳定币规则从2024年6月30日适用，服务商规则从2024年12月30日适用，各成员国的过渡期最晚到2026年7月1日。"},{"q":"MiCA对USDT有什么影响？","a":"受MiCA约束的平台需要遵守稳定币授权要求，因此一些交易所限制了欧洲经济区用户交易未获授权的稳定币，具体做法以平台公告为准。"}],"title":"什么是MiCA？欧盟加密资产市场法规要点","description":"MiCA是什么？了解欧盟加密资产市场法规的生效时间、对稳定币和交易所的要求，以及过渡期和CASP护照机制。","related":[["vasp","虚拟资产服务提供商（VASP）","VASP是“虚拟资产服务提供商”的缩写，指为他人提供加密资产兑换、转账、托管或发行相关服务的企业，例如中心化交易所和托管钱包服务商。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["usdc","USDC（美元币）","USDC 是由 Circle 公司发行、与美元 1:1 挂钩的稳定币，储备主要为现金和短期美国国债，以储备披露较透明著称，在 DeFi 和合规场景中使用广泛。"],["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"先认门，再注册：别把账户开在假平台"},"coin":null,"tool":null,"cta":false},"dual-investment":{"slug":"dual-investment","cat":"exchange-features","en":"Dual investment","contentLocale":"zh-Hans","term":"双币投资（Dual investment）","aka":["双币赢","双币理财","Dual investment"],"short":"双币投资是一种结构化理财产品：你选择目标价格和期限并获得较高的约定收益，到期时根据结算价与目标价的关系，用原币种或另一种币种连本带息结算。","body":[["双币投资分为“低买”和“高卖”两种。低买：你投入",["稳定币","stablecoin"],"，设定一个低于现价的目标价，到期价格不高于目标价，就按目标价把本息换成币；价格高于目标价，就收回稳定币加利息。高卖：你投入币，设定高于现价的目标价，到期价格不低于目标价就换成稳定币，否则收回币加利息。"],"它的本质类似卖出期权：较高的收益来自你承担了被动换币的义务。无论哪种结果，你都能拿到约定利息，但不能保证你最终资产的价值不缩水。","最大的风险是行情剧烈波动时被以不理想的价格换币：低买时价格暴跌，你会以目标价接到一堆市价更低的币；高卖时价格暴涨，你只能按目标价卖出，错过后面的涨幅。产品一旦申购通常不能提前赎回。"],"example":["假设BTC现价60,000 ",["USDT","usdt"],"，你选择“低买”，投入5,700 USDT，目标价57,000，期限7天，年化30%。到期利息为5,700 × 30% × 7 ÷ 365 ≈ 32.79 USDT。如果结算价是59,000，高于目标价，你收回5,732.79 USDT；如果结算价是54,000，低于目标价，你会按57,000买入，得到5,732.79 ÷ 57,000 ≈ 0.1006 ",["BTC","bitcoin"],"，按54,000计算",["市值","market-capitalization"],"约5,431 USDT，比投入的5,700 USDT少约269 USDT。"],"mistakes":["把年化收益当成稳赚的利息，忽略到期被动换币可能带来的亏损。","低买时目标价设得离现价太近，只为追求更高年化。","把短期急用的资金投入，产品到期前无法赎回。"],"faq":[{"q":"双币投资保本吗？","a":"不保本。利息一定能拿到，但可能以另一种币种结算，按结算后的市价计算，总价值可能低于投入金额。"},{"q":"双币投资适合什么人？","a":"适合本来就打算在某个价格买入或卖出、能接受以另一种币结算的人，不适合把它当成无风险收益产品。"}],"title":"什么是双币投资？低买高卖的收益与风险","description":"双币投资是什么？用具体数字讲解低买和高卖两种方向如何结算、高年化收益从哪里来，以及到期被动换币的亏损风险。","related":[["options","加密期权（Crypto Options）","加密期权是一种合约，买方支付权利金后，获得在到期日以约定行权价买入（看涨期权）或卖出（看跌期权）某种加密资产的权利，但没有义务。"],["crypto-earn","理财/赚币（Crypto Earn）","理财（赚币）是交易所提供的加密资产收益产品，把你账户里的闲置币放进活期或定期产品中，由平台通过借贷、质押或其他方式产生收益并按约定发放。"],["apr-vs-apy","APR 和 APY 的区别","APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"]],"lesson":null,"coin":null,"tool":null,"cta":false},"unified-trading-account":{"slug":"unified-trading-account","cat":"exchange-features","en":"Unified trading account (UTA)","contentLocale":"zh-Hans","term":"统一账户（Unified trading account）","aka":["统一交易账户","UTA","统一保证金账户"],"short":"统一账户是交易所把现货、杠杆、合约和期权等交易放在同一个账户中的模式，账户里多种资产可以按折算率共同作为保证金，盈亏可以相互抵消。","body":[["传统模式下，现货账户、合约账户各自独立，你要先把USDT划转到合约账户才能开仓。统一账户取消了这一步：账户内的USDT、",["BTC","bitcoin"],"、ETH等资产都可以按一定折算率计入保证金，一个仓位的浮盈也可以支撑另一个仓位。"],["这样做的好处是资金效率更高，不用频繁划转，",["对冲","hedging"],"仓位（如现货多单加合约空单）占用的保证金也更少。部分平台还在统一账户中提供",["组合保证金模式","portfolio-margin"],"，按整体风险而不是单个仓位计算保证金要求。"],["风险在于所有资产被绑在一起：在",["全仓模式","cross-margin"],"下，一个仓位的大幅亏损会消耗整个账户的保证金，严重时账户内的现货也可能被用于平仓。不同",["交易所","centralized-exchange"],"的统一账户名称、可选模式和币种折算率都不同，开通前要看清规则。"]],"example":["假设你的统一账户里有10,000 USDT和0.5 BTC，BTC价格60,000 ",["USDT","usdt"],"，平台给BTC的保证金折算率为95%。BTC的保证金价值为0.5 × 60,000 × 95% = 28,500 USDT，加上USDT，账户可用保证金约38,500 USDT。如果BTC下跌10%到54,000，BTC部分的保证金价值降为25,650 USDT，总保证金减少2,850 USDT，即使你的合约仓位没有亏损，可用保证金也会同步变少。"],"mistakes":["以为现货资产和合约仓位是隔开的，没意识到合约亏损可能动用现货。","忽视折算率，把币的全部市值都当成可用保证金。","在统一账户里用全仓开高杠杆，一次行情把整个账户的资金拖入强平风险。"],"faq":[{"q":"统一账户适合新手吗？","a":"如果只做现货，影响不大；如果做合约，建议先理解全仓和逐仓的区别，必要时用逐仓或子账户隔离风险。"},{"q":"统一账户里的币为什么要打折算保证金？","a":"因为币价会波动，平台用低于100%的折算率给保证金留出安全空间，波动越大的币折算率通常越低。"}],"title":"什么是统一账户？保证金折算率与风险","description":"交易所统一账户是什么？了解统一交易账户如何合并现货和合约保证金、币种折算率怎么算，以及全仓模式下相互牵连的风险。","related":[["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。"],["portfolio-margin","组合保证金（Portfolio Margin）","组合保证金是一种按整个投资组合的净风险计算保证金的模式，现货、合约、期权的仓位可以互相抵消风险，对冲良好的组合所需保证金更低。"],["sub-account","子账户（Sub-account）","子账户是在同一个交易所主账户下开设的独立交易账户，资产和仓位彼此隔离，可以分别用于不同策略、API机器人或资金用途，并由主账户统一管理。"],["margin-trading","杠杆交易（Margin Trading）","杠杆交易是用自己的资金作保证金，向交易所借入资金或币来放大买卖规模的交易方式，借款要付利息，亏损到一定程度会被强平。"]],"lesson":null,"coin":null,"tool":null,"cta":true},"withdrawal-fee":{"slug":"withdrawal-fee","cat":"exchange-features","en":"Withdrawal fee","contentLocale":"zh-Hans","term":"提币手续费（Withdrawal fee）","aka":["提币费","提现手续费","Withdrawal fee"],"short":"提币手续费是你把加密资产从交易所转出到外部地址时，交易所收取的费用，通常按币种和网络收取固定数量，用于覆盖链上Gas费和平台的处理成本。","body":[["同一种币在不同网络上的提币费可能差很多。以USDT为例，它可以在",["以太坊","ethereum"],"（ERC20）、波场（TRC20）、BNB Chain、Solana以及多个",["二层网络","layer-2"],"上转账，各网络的Gas费不同，",["交易所","centralized-exchange"],"设置的提币费也不同，二层网络和低费用公链往往更便宜。"],"多数交易所按固定数量收取，与提币金额无关，所以小额提币时费用占比会很高。部分平台会根据链上拥堵情况动态调整费用，也有平台对同一交易所内部转账免费。","选择网络时，最重要的是确保接收方支持同一网络：把TRC20的USDT提到只支持ERC20的地址，可能导致资产丢失或需要高昂的找回费用。提币前在提币页面核对“网络”“到账数量”和“最小提币额”三项。"],"example":["假设你要把100 USDT提到朋友的钱包。提币页面显示：ERC20",["网络手续费","gas-fee"],"5 ",["USDT","usdt"],"，TRC20网络手续费1 USDT。走ERC20时实际到账95 USDT，手续费占5%；走TRC20时到账99 USDT，只占1%。如果你一次性提1,000 USDT，ERC20的手续费占比降到0.5%。前提是朋友的钱包支持你选择的网络，否则省下的手续费可能远比不上丢币的损失。"],"mistakes":["提币时随便选择网络，没有确认接收方是否支持该网络。","频繁小额提币，固定手续费累计起来占比很高。","只看到账数量，不检查最小提币额，导致提币申请失败或余额卡住。"],"faq":[{"q":"为什么不同网络的提币费不一样？","a":"因为各条链的Gas费和处理成本不同，交易所据此为每个网络单独设置费用，高费用的链提币费通常更高。"},{"q":"提币手续费能退吗？","a":"提币一旦在链上发出，手续费一般不退。如果提币申请在发出前被取消或审核未通过，费用通常会随本金一起退回。"}],"title":"什么是提币手续费？不同网络费用对比","description":"提币手续费是什么？了解为什么同一种币在ERC20、TRC20等不同网络上手续费不同、固定费率对小额提币的影响，以及选错网络的风险。","related":[["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"],["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。"],["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"],["layer-2","二层网络（Layer 2，L2）","二层网络（L2）是建立在一层区块链之上的扩容方案，在二层批量处理交易后把结果提交回主链，以更低的费用借用主链安全性。"]],"lesson":{"id":"E08","slug":"sell-vs-withdraw","ep":8,"title":"卖出以后，钱为什么没到银行卡？"},"coin":null,"tool":"/rates","cta":false}});
